<?php
namespace Tests\Feature\Adjustment; use App\Models\{DocumentSequence,ItemLedger,User}; use App\Services\Adjustment\AdjustmentService; use DomainException; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class AdjustmentTest extends TestCase { use RefreshDatabase; private function sequence(): void {DocumentSequence::create(['code'=>'ADJ','prefix'=>'ADJ','date_format'=>'ymd','separator'=>'/','padding'=>4,'reset_period'=>'daily','is_active'=>true]);} public function test_item_reversal_creates_opposite_movement(): void {$this->sequence();$admin=User::factory()->create();$source=ItemLedger::factory()->create(['qty_in'=>0,'qty_out'=>10,'posted_by'=>$admin->id]);$adj=app(AdjustmentService::class)->reverse('item',$source->id,'Wrong quantity posted',$admin);$reversal=ItemLedger::findOrFail($adj->reversal_entry_id);$this->assertSame(10.0,(float)$reversal->qty_in);$this->assertSame(0.0,(float)$reversal->qty_out);$this->assertSame($source->id,$reversal->reversal_of_id);} public function test_duplicate_reversal_is_rejected(): void {$this->sequence();$admin=User::factory()->create();$source=ItemLedger::factory()->create(['posted_by'=>$admin->id]);$service=app(AdjustmentService::class);$service->reverse('item',$source->id,'First correction reason',$admin);$this->expectException(DomainException::class);$service->reverse('item',$source->id,'Second correction reason',$admin);} }
